create or replace function public.get_admin_payments_filtered(p_search text default null,p_status text default null) returns table(reference text,event_name text,organization_name text,status text,gross_minor bigint,refunded_minor bigint,provider_fee_minor bigint,created_at timestamptz) language sql stable security definer set search_path='' as $$ select p.provider_reference,e.name,o.name,coalesce(l.status,p.status),p.total_amount_minor,coalesce(l.refunded_amount_minor,0),coalesce(l.provider_fee_minor,0),p.created_at from public.payment_attempts p join public.organizations o on o.id=p.organization_id left join public.events e on e.id=p.event_id left join public.paid_vote_ledger l on l.reference=p.provider_reference where exists(select 1 from public.platform_admins a where a.user_id=auth.uid() and a.is_active) and (p_search is null or p.provider_reference ilike '%'||p_search||'%' or e.name ilike '%'||p_search||'%' or o.name ilike '%'||p_search||'%') and (p_status is null or coalesce(l.status,p.status)=p_status) order by p.created_at desc limit 500; $$;
revoke all on function public.get_admin_payments_filtered(text,text) from public,anon; grant execute on function public.get_admin_payments_filtered(text,text) to authenticated;
